                + " VALUES (?, ?, ?) ON DUPLICATE KEY UPDATE"
                + " status=?,"
                + " finished_time=?,"
                + " cost=( (executor_memory_mb * number_executor + driver_memory_mb) * ? "
                + " + (executor_core * number_executor + driver_core) * ? "
                + ")"
                + " * (TIMESTAMPDIFF(second,start_time,finished_time))",
            dbName);
