import org.junit.jupiter.api.Test;
import com.apple.spark.util.TimerMetricContainer;
import com.apple.spark.util.CounterMetricContainer;

public class LogDaoTest {

  private static void setField(Object target, String fieldName, Object value) throws Exception {
    Field f = findField(target.getClass(), fieldName);
    f.setAccessible(true);
    f.set(target, value);
  }

  private static Field findField(Class<?> clazz, String name) throws NoSuchFieldException {
    Class<?> c = clazz;
    while (c != null) {
      try {
        return c.getDeclaredField(name);
      } catch (NoSuchFieldException e) {
        c = c.getSuperclass();
      }
    }
    throw new NoSuchFieldException(name);
  }

  @Test
  public void testBypassLogDoesNothing() throws Exception {
    // create instance with empty connection string -> bypassLog == true
    LogDao dao = new LogDao("", "u", "p", "db", new LoggingMeterRegistry());

    // replace the timerMetrics with a mock to assert it is not invoked
    TimerMetricContainer mockTimer = mock(TimerMetricContainer.class);
    setField(dao, "timerMetrics", mockTimer);

    // Call method; since bypassLog is true, timerMetrics.record should not be called
    dao.logApplicationFinished("sub-1", "FINISHED", new Timestamp(System.currentTimeMillis()), 1.0, 2.0);

    verifyNoInteractions(mockTimer);
  }

  @Test
  public void testLogApplicationFinishedSuccessfulExecutesStatement() throws Exception {
    // create dao with empty connection string so it doesn't attempt real DB setup
    LogDao dao = new LogDao("", "u", "p", "mydb", new LoggingMeterRegistry());

    // Prepare mocks for DBConnection, Connection, PreparedStatement
    DBConnection mockDbConn = mock(DBConnection.class);
    Connection mockConnection = mock(Connection.class);
    PreparedStatement mockStmt = mock(PreparedStatement.class);

    when(mockDbConn.getConnection()).thenReturn(mockConnection);
    when(mockConnection.prepareStatement(anyString())).thenReturn(mockStmt);

    // Replace dbConnection
    setField(dao, "dbConnection", mockDbConn);

    // Ensure bypassLog is false so logging will occur
    setField(dao, "bypassLog", false);

    // Replace timerMetrics with one that immediately runs the runnable
    TimerMetricContainer immediateTimer =
        new TimerMetricContainer(new LoggingMeterRegistry()) {
          @Override
          public void record(Runnable runnable, String metricName, io.micrometer.core.instrument.Tag... tags) {
            runnable.run();
          }
        };
    setField(dao, "timerMetrics", immediateTimer);

    // Replace failureMetrics with mock to ensure it's not called
    CounterMetricContainer mockFailure = mock(CounterMetricContainer.class);
    setField(dao, "failureMetrics", mockFailure);

    // Call method with test data
    String submissionId = "sub-123";
    String status = "FINISHED";
    Timestamp finishedTime = Timestamp.valueOf("2020-01-01 12:00:00");
    Double vCoreCost = 3.14;
    Double memCost = 6.28;

    dao.logApplicationFinished(submissionId, status, finishedTime, vCoreCost, memCost);

    // Verify that PreparedStatement was created and parameters were set accordingly
    verify(mockConnection, times(1)).prepareStatement(anyString());
    verify(mockStmt, times(1)).setString(1, submissionId);
    verify(mockStmt, times(1)).setString(2, status);
    verify(mockStmt, times(1)).setTimestamp(3, finishedTime);
    verify(mockStmt, times(1)).setString(4, status);
    verify(mockStmt, times(1)).setTimestamp(5, finishedTime);
    verify(mockStmt, times(1)).setDouble(6, memCost);
    verify(mockStmt, times(1)).setDouble(7, vCoreCost);
    verify(mockStmt, times(1)).executeUpdate();

    // Ensure failure metric not incremented
    verifyNoInteractions(mockFailure);
  }

  @Test
  public void testLogApplicationFinishedHandlesExceptionAndIncrementsFailureMetric() throws Exception {
    LogDao dao = new LogDao("", "u", "p", "mydb", new LoggingMeterRegistry());

    // Prepare mocks
    DBConnection mockDbConn = mock(DBConnection.class);
    Connection mockConnection = mock(Connection.class);
    PreparedStatement mockStmt = mock(PreparedStatement.class);

    when(mockDbConn.getConnection()).thenReturn(mockConnection);
    when(mockConnection.prepareStatement(anyString())).thenReturn(mockStmt);

    // Make executeUpdate throw SQLException
    doThrow(new SQLException("boom")).when(mockStmt).executeUpdate();

    setField(dao, "dbConnection", mockDbConn);
    setField(dao, "bypassLog", false);

    TimerMetricContainer immediateTimer =
        new TimerMetricContainer(new LoggingMeterRegistry()) {
          @Override
          public void record(Runnable runnable, String metricName, io.micrometer.core.instrument.Tag... tags) {
            runnable.run();
          }
        };
    setField(dao, "timerMetrics", immediateTimer);

    CounterMetricContainer mockFailure = mock(CounterMetricContainer.class);
    setField(dao, "failureMetrics", mockFailure);

    // Invoke
    dao.logApplicationFinished("sub-err", "FAILED", new Timestamp(System.currentTimeMillis()), 0.5, 0.5);

    // Verify executeUpdate attempted
    verify(mockStmt, times(1)).executeUpdate();

    // Verify failureMetrics.increment was called with expected tags: operation=log_app_finished and exception=SQLException
    // Capture arguments
    @SuppressWarnings("unchecked")
    org.mockito.ArgumentCaptor<io.micrometer.core.instrument.Tag[]> tagsCaptor =
        org.mockito.ArgumentCaptor.forClass(io.micrometer.core.instrument.Tag[].class);
    org.mockito.ArgumentCaptor<String> metricNameCaptor = org.mockito.ArgumentCaptor.forClass(String.class);

    verify(mockFailure, times(1)).increment(metricNameCaptor.capture(), tagsCaptor.capture());

    String metricName = metricNameCaptor.getValue();
    io.micrometer.core.instrument.Tag[] tags = tagsCaptor.getValue();

    assertNotNull(metricName);
    assertNotNull(tags);
    boolean foundOperation = false;
    boolean foundException = false;
    for (Tag t : tags) {
      if ("operation".equals(t.getKey()) && "log_app_finished".equals(t.getValue())) {
        foundOperation = true;
      }
      if ("exception".equals(t.getKey()) && "SQLException".equals(t.getValue())) {
        foundException = true;
      }
    }
    assertTrue(foundOperation, "operation tag with log_app_finished should be present");
    assertTrue(foundException, "exception tag with SQLException should be present");
  }
}

